def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'
    if not is_valid(*start) or not is_valid(*goal):
        return []
    if start == goal:
        return [start]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    stack = [(start, [start])]
    visited = {start}
    while stack:
        current, path = stack.pop()
        if current == goal:
            return path
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            next_cell = (nr, nc)
            if is_valid(nr, nc) and next_cell not in visited:
                visited.add(next_cell)
                new_path = path + [next_cell]
                stack.append((next_cell, new_path))
    return []

