def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    if not is_valid(start) or not is_valid(goal):
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    visited.add(start)

    def dfs(current):
        if current == goal:
            return [current]
        for dr, dc in directions:
            nr = current[0] + dr
            nc = current[1] + dc
            next_pos = (nr, nc)
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and next_pos not in visited:
                visited.add(next_pos)
                res = dfs(next_pos)
                if res is not None:
                    return [current] + res
                visited.remove(next_pos)
        return None

    result = dfs(start)
    return result if result else []

