def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows = len(grid)
    cols = len(grid[0])
    sr, sc = start
    er, ec = goal

    # Check if start or goal are out of bounds
    if not (0 <= sr < rows and 0 <= sc < cols and 0 <= er < rows and 0 <= ec < cols):
        return []

    # Check if start or goal are walls
    if grid[sr][sc] == '#' or grid[er][ec] == '#':
        return []

    # Check if start is goal
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    path = []
    visited.add(start)
    path.append(start)

    def dfs(current):
        if current == goal:
            return True
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            next_cell = (nr, nc)
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] != '#' and next_cell not in visited:
                    visited.add(next_cell)
                    path.append(next_cell)
                    if dfs(next_cell):
                        return True
                    visited.remove(next_cell)
                    path.pop()
        return False

    if dfs(start):
        return path
    else:
        return []

